# Format Migration Manager demo: batched conversion with semantic verification.
OLD=[{"id":"f1","rows":[["a",1],["b",2]]},{"id":"f2","rows":[["c",3]]}]
def convert(f):  # old: list-of-rows -> new: list-of-dicts
    return {"id":f["id"],"records":[{"k":r[0],"v":r[1]} for r in f["rows"]]}
def verify(old,new):
    return sorted((r[0],r[1]) for r in old["rows"])==sorted((d["k"],d["v"]) for d in new["records"])
for f in OLD:
    new=convert(f); print(f["id"],"converted, faithful:" ,verify(f,new))
print("dual-read active; old copies retained until soak period passes")

